"""UserPromptSubmit hook for Claude Code and Codex: adds skill suggestions as context.

The hook never blocks a prompt. Anything short of confident suggestions,
including every error, prints nothing and exits 0.
"""

from __future__ import annotations

import json
import sys
from pathlib import Path
from typing import Any, TextIO

from .catalog import default_actions_path, default_skills_dir
from .cli import pick

# Replies like "yupp" or "go on" are never new tasks, so they skip the API call.
MIN_WORDS = 3
CONTEXT_CHARS = 2_000
TRANSCRIPT_TAIL_BYTES = 512 * 1024
ASSISTANT_TEXT_BLOCKS = {"text", "output_text"}


def _assistant_text(record: Any) -> str | None:
    if not isinstance(record, dict) or record.get("isSidechain"):
        return None
    # Claude Code nests the message under "message", Codex under "payload".
    message = record.get("message") or record.get("payload")
    if not isinstance(message, dict) or message.get("role") != "assistant":
        return None
    content = message.get("content")
    if not isinstance(content, list):
        return None
    texts = [
        block["text"]
        for block in content
        if isinstance(block, dict)
        and block.get("type") in ASSISTANT_TEXT_BLOCKS
        and isinstance(block.get("text"), str)
    ]
    return "\n".join(texts).strip() or None


def last_assistant_text(path: Path | None) -> str:
    """Return the end of the agent's latest main-thread reply, or "" if none."""
    if path is None:
        return ""
    try:
        with path.open("rb") as transcript:
            transcript.seek(0, 2)
            size = transcript.tell()
            transcript.seek(max(0, size - TRANSCRIPT_TAIL_BYTES))
            tail = transcript.read().decode("utf-8", errors="replace")
    except OSError:
        return ""

    for line in reversed(tail.splitlines()):
        try:
            record = json.loads(line)
        except json.JSONDecodeError:
            continue
        if text := _assistant_text(record):
            return text[-CONTEXT_CHARS:]
    return ""


def _context(suggestions: list[dict[str, Any]]) -> str:
    lines = [
        f"- {suggestion['invocation']}: {suggestion['description']}"
        for suggestion in suggestions
    ]
    return (
        "skill-picker found actions that may fit this request:\n"
        + "\n".join(lines)
        + "\nBefore starting, show these to the user with a one-line reason "
        "each and ask which to use. If the user already chose how to proceed, "
        "ignore this."
    )


def main(stdin: TextIO = sys.stdin, stdout: TextIO = sys.stdout) -> int:
    # A failing hook would interrupt the user's prompt, so every failure is silent.
    try:
        event = json.load(stdin)
        prompt = event.get("prompt") if isinstance(event, dict) else None
        if not isinstance(prompt, str) or len(prompt.split()) < MIN_WORDS:
            return 0
        transcript = event.get("transcript_path")
        result = pick(
            prompt.strip(),
            default_skills_dir(),
